import {calendarDate,quantity,periodText} from './polish.js';
import {CALCULATOR_LABELS} from './calculator-engine.js';
export const calcEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const calcMoney=value=>value===null||value===undefined?'Do ustalenia':new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN'}).format(value);
export const calcIcon=()=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="2" width="16" height="20" rx="3"/><path d="M8 6h8M8 10h1m6 0h1M8 14h1m6 0h1M8 18h1m6 0h1"/></svg>';
export const calcParentLabel=(input,index)=>input.familyType==='birth'?(index?'Ojciec / uprawniony opiekun':'Matka'):`Rodzic / opiekun ${index+1}`;
export function calcField(input,path,label,{type='number',help='',min='0',max='',step='any',placeholder='',required=false}={}){
  const value=path.split('.').reduce((o,k)=>o?.[k],input);
  return `<label class="calc-field" data-field-label="${path}"><span>${label}</span><input data-calc-field="${path}" name="${path}" type="${type}" value="${calcEscape(value??'')}" ${type==='number'?`min="${min}" ${max?`max="${max}"`:''} step="${step}"`:''} ${placeholder?`placeholder="${calcEscape(placeholder)}"`:''} ${required?'required':''}>${help?`<small>${help}</small>`:''}</label>`;
}
export function calcSelect(input,path,label,options,help=''){
  const value=path.split('.').reduce((o,k)=>o?.[k],input);
  return `<label class="calc-field" data-field-label="${path}"><span>${label}</span><select data-calc-field="${path}" name="${path}">${options.map(([id,text])=>`<option value="${id}" ${String(value)===String(id)?'selected':''}>${text}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</label>`;
}
export function calcCheck(input,path,label,help=''){const value=path.split('.').reduce((o,k)=>o?.[k],input);return `<label class="calc-check"><input type="checkbox" data-calc-field="${path}" name="${path}" ${value?'checked':''}><span>${label}${help?`<small>${help}</small>`:''}</span></label>`;}
export const calcDisclosure=(title,body,open=false)=>`<details class="calc-details" ${open?'open':''}><summary>${title}</summary><div>${body}</div></details>`;
const calcStatus={potential:'Podstawowe warunki spełnione',conditional:'Możliwe prawo — sprawdź warunki',unknown:'Potrzebne dodatkowe dane',assessment:'Wymaga ustalenia przez ZUS',no:'Brak prawa z podanego tytułu',blocked:'Wypłata wstrzymana — zadłużenie',waiting:'Okres wyczekiwania'};
export function calculatorResultHtml(result,recordId){
  const i=result.input,periods=result.periods,renderSource=s=>`<a href="${calcEscape(s.url+(s.quote?'#:~:text='+encodeURIComponent(s.quote):''))}" target="_blank" rel="noopener noreferrer">${calcEscape(s.name)}<small>${calcEscape(s.section)}</small></a>`;
  const card=result.parents?.map((parent,index)=>`<article class="calc-parent-result"><span class="eyebrow">${calcParentLabel(i,index)}</span><h3>${calcStatus[parent.status]||'Sprawdź dane'}</h3><p class="calc-value">${calcMoney(result.totals[index]?.gross)}<small>Łączny zasiłek brutto w zaplanowanych okresach</small></p><dl><div><dt>Podstawa wyjściowa</dt><dd>${calcMoney(parent.basis)}</dd></div><div><dt>Zaplanowany okres</dt><dd>${quantity(result.totals[index]?.days||0,'days')}</dd></div></dl>${parent.notes.length?calcDisclosure('Dlaczego taki wynik?',parent.notes.map(n=>`<p>${calcEscape(n)}</p>`).join('')):''}</article>`).join('')||'';
  const start=periods.length?periods.map(p=>p.start).sort()[0]:null,end=periods.length?periods.map(p=>p.end).sort().at(-1):null;
  return `<section class="calc-results" aria-live="polite"><div class="calc-result-heading"><span class="eyebrow">Wasz scenariusz</span><h2>${calcEscape(result.title)}</h2><p>Obliczenia na podstawie podanych danych. Prawo do wypłaty potwierdza właściwy płatnik lub ZUS.</p></div>${result.warnings.length?`<div class="calc-notice">${result.warnings.map(w=>`<p>${calcEscape(w)}</p>`).join('')}</div>`:''}<div class="calc-parent-results">${card}</div>${result.business?`<div class="calc-parent-results"><article class="calc-parent-result"><h3>Ulga na start</h3><strong>${result.business.startEligible?'Podstawowe warunki spełnione':'Nie potwierdzono warunków'}</strong><p>${result.business.startEnd?'Do '+calendarDate(result.business.startEnd):'Sprawdź wcześniejszą działalność i pozostałe wyłączenia.'}</p></article><article class="calc-parent-result"><h3>Podstawy składek</h3><p>Preferencyjna: <strong>${calcMoney(result.business.preferentialBasis)}</strong></p><p>Mały ZUS Plus: <strong>${calcMoney(result.business.smallBasis)}</strong></p><p>Zwykła podstawa JDG: <strong>${calcMoney(result.business.regularBasis)}</strong></p><p>Limit dobrowolnego chorobowego: <strong>${calcMoney(result.business.sicknessCap)}</strong></p><small>To podstawa składek, nie kwota zasiłku ani wypłata dla rodzica.</small></article></div>`:''}
    ${result.variants.length?`<section class="calc-section"><h3>Porównanie wariantów dla tego samego planu</h3><div class="calc-variants">${result.variants.map(v=>`<article><h4>${v.label}</h4>${v.available?v.gross.map((amount,index)=>`<p>${calcParentLabel(i,index)}: <strong>${calcMoney(amount)}</strong></p>`).join(''):'<p>Brak potwierdzenia terminowego wniosku dla tego wariantu.</p>'}</article>`).join('')}</div><p class="field-help">Porównujemy zasiłek brutto za wpisane okresy, z własnej podstawy każdego rodzica. Nie zakładamy, że cały wspólny wymiar wykorzysta jedna osoba.</p></section>`:''}
    <section class="calc-section"><h3>Wasz plan w czasie</h3>${periods.length?`<div class="calc-timeline" aria-label="Okresy scenariusza">${periods.map(p=>`<article class="calc-timeline-row parent-${p.parent}"><div><strong>${calcEscape(p.title)}</strong><span>${calcParentLabel(i,p.parent)} · ${periodText(p)}</span><small>${quantity(p.days,'days')}${p.rate?' · '+p.rate.toLocaleString('pl-PL')+'% podstawy':''}${p.work?' · praca '+p.work.toLocaleString('pl-PL')+' etatu':''}${p.daily!==null?' · stawka dzienna '+calcMoney(p.daily):''}</small></div><b>${calcMoney(p.gross)}</b></article>`).join('')}</div>`:'<p>Brak okresu do zapisania. Wynik wskazuje warunki wymagające sprawdzenia.</p>'}</section>
    ${result.monthly.length?calcDisclosure('Wypłaty w poszczególnych miesiącach',`<div class="calc-table-scroll"><table><thead><tr><th>Miesiąc</th><th>Rodzic</th><th>Dni</th><th>Zasiłek brutto</th></tr></thead><tbody>${result.monthly.map(m=>`<tr><td>${m.month}</td><td>${calcParentLabel(i,m.parent)}</td><td>${m.days}</td><td>${calcMoney(m.gross)}</td></tr>`).join('')}</tbody></table></div><p>Wyliczono dzienną stawkę po zaokrągleniu do groszy × rzeczywistą liczbę dni. „Do ustalenia” oznacza brak danych lub niepotwierdzone uprawnienie.</p>`):''}
    ${result.topUps.length?`<section class="calc-section"><h3>Podwyższenie do świadczenia rodzicielskiego</h3>${result.topUps.map(t=>`<p>${calcParentLabel(i,t.parent)} · ${t.month}: próg ${calcMoney(t.threshold)}, podana suma po PIT ${calcMoney(t.netReceived)}, możliwe podwyższenie <strong>${calcMoney(t.topUp)}</strong>.</p>`).join('')}<p>Warunek: wskazana kwota jest łączną kwotą netto właściwych świadczeń z wszystkich tytułów w tym miesiącu. Ojcowski i szczególny zasiłek przed porodem nie wchodzą do tego porównania.</p></section>`:''}
    <section class="calc-section"><h3>Dokumenty — co i gdzie złożyć</h3>${result.documents.map(d=>`<article class="calc-document-card"><h4>${calcParentLabel(i,d.parent)}</h4><p><strong>${calcEscape(d.recipient)}</strong></p><ul>${d.items.map(item=>`<li>${calcEscape(item)}</li>`).join('')}</ul><div class="calc-links">${d.forms.map(f=>`<a href="${f.url}" target="_blank" rel="noopener noreferrer">${f.code} — formularze ZUS</a>`).join('')}</div></article>`).join('')}</section>
    ${result.deadlines.length?`<section class="calc-section"><h3>Terminy i przypomnienia do kalendarza</h3>${result.deadlines.map(d=>`<article class="calc-deadline"><strong>${calendarDate(d.start,{long:true})}</strong><span>${calcEscape(d.title)}</span>${d.description?`<small>${calcEscape(d.description)}</small>`:''}</article>`).join('')}</section>`:''}
    ${calcDisclosure('Założenia, ograniczenia i ryzyka',result.facts.concat(result.generalGuidance).map(f=>`<p>${calcEscape(f)}</p>`).join(''))}
    ${result.support.length?`<section class="calc-section"><h3>Wsparcie w trudnej sytuacji</h3><p>Możecie skorzystać z pomocy organizacji charytatywnych. Poniżej wskazujemy konkretne bezpłatne formy wsparcia; dostępność sprawdźcie na ich stronach.</p><div class="calc-support">${result.support.map(s=>`<article><h4>${s.name}</h4><p>${s.description}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">Sprawdź pomoc</a>${s.phone?`<a href="tel:${s.phone}">${s.phone}</a>`:''}${s.email?`<a href="mailto:${s.email}">${s.email}</a>`:''}</article>`).join('')}</div></section>`:''}
    <section class="calc-section"><h3>Oficjalne źródła tego wyniku</h3><div class="calc-source-grid">${result.sources.map(renderSource).join('')}</div><p class="field-help">Zasady: ${calcEscape(result.rulesVersion)} · weryfikacja ${calendarDate(result.reviewedAt)}. Zapisany wynik zachowuje swoją wersję; po zmianie przepisów możecie go ponownie przeliczyć.</p></section>
    <section class="calc-save-panel"><label class="calc-field"><span>Nazwa scenariusza</span><input id="calc-case-title" maxlength="160" value="${calcEscape(result.caseTitle||result.title)}" placeholder="Np. nasz plan po narodzinach"></label><button class="primary" id="calc-save">${recordId?'Zapisz zmiany i terminy':'Zapisz wynik i terminy w kalendarzu'}</button><div class="calc-action-row"><button class="secondary" id="calc-export">Pobierz podsumowanie</button><button class="secondary" id="calc-applications">Przygotuj wniosek — symulacja</button></div></section></section>`;
}
